# Bank zadań autorskich — biologia, część 1: Umiejętności egzaminacyjne (metodologia, dane, czasowniki).
# B(tytuł, materiał, *zadania); T(typ, punkty, polecenie, odpowiedź, omówienie)
BANK = {'umiejetnosci': [
 B('Katalaza w ziemniaku',
   'Doświadczenie (autorskie). Uczniowie umieścili w czterech probówkach po 5 g startego surowego ziemniaka i dodali po 5 cm³ 3% roztworu H₂O₂. Probówki inkubowano 10 minut w temperaturze: 0°C, 20°C, 40°C i 80°C. Mierzono wysokość piany (cm) powstałej z wydzielanego tlenu. Wyniki: 0°C — 0,8; 20°C — 2,5; 40°C — 4,1; 80°C — 0,2.',
   T('podaj', 1, 'Sformułuj problem badawczy tego doświadczenia.', 'Np. Czy (jak) temperatura wpływa na aktywność katalazy w bulwie ziemniaka?', 'Problem to pytanie zawierające zmienną niezależną (temperatura) i zależną (aktywność katalazy mierzona ilością piany).'),
   T('podaj', 1, 'Określ zmienną niezależną i zmienną zależną w doświadczeniu.', 'Niezależna — temperatura; zależna — wysokość piany (ilość wydzielonego tlenu, aktywność katalazy).', 'Niezależną zmienia badacz, zależną mierzy.'),
   T('podaj', 1, 'Zaproponuj próbę kontrolną, która wykaże, że piana powstaje z udziałem enzymu z ziemniaka.', 'Np. probówka z H₂O₂ i ugotowanym (zagotowanym) ziemniakiem albo z samą wodą zamiast ziemniaka — piana nie powstanie.', 'Gotowanie denaturuje enzym; brak piany w tej próbie pokazuje, że to enzym rozkłada H₂O₂.'),
   T('wyjasnij', 1, 'Wyjaśnij, dlaczego w temperaturze 80°C powstało bardzo mało piany.', 'Wysoka temperatura spowodowała denaturację katalazy — zmienił się kształt centrum aktywnego, więc H₂O₂ nie mógł się z nim wiązać i nie był rozkładany.', 'Pełne wyjaśnienie: przyczyna (80°C) → mechanizm (denaturacja, zmiana centrum aktywnego) → skutek (brak rozkładu, mało tlenu).'),
   T('rozstrzygnij', 1, 'Rozstrzygnij, czy na podstawie wyników można stwierdzić, że optimum temperaturowe katalazy wynosi dokładnie 40°C. Uzasadnij.', 'Nie — zbadano tylko cztery temperatury; optimum może leżeć np. między 20 a 80°C (np. 35 lub 50°C), których nie badano.', 'Wniosek nie może wykraczać poza dane — klasyczna pułapka z rekomendacji CKE 2026.')),
 B('Kiełkowanie rzeżuchy',
   'Doświadczenie (autorskie). W czterech szalkach na wilgotnej ligninie wysiano po 50 nasion rzeżuchy. Szalki umieszczono w temperaturze 22°C: A — na świetle, B — w ciemności, C — na świetle, ale na suchej ligninie, D — w ciemności i w lodówce (4°C). Po 3 dniach wykiełkowało: A — 46, B — 47, C — 0, D — 3 nasiona.',
   T('podaj', 1, 'Podaj, które dwie szalki należy porównać, aby ocenić wpływ światła na kiełkowanie.', 'A i B.', 'Różnią się tylko światłem; pozostałe warunki (woda, temperatura) są takie same.'),
   T('rozstrzygnij', 1, 'Rozstrzygnij, czy porównanie szalek A i D pozwala ocenić wpływ temperatury na kiełkowanie. Uzasadnij.', 'Nie — szalki różnią się dwoma czynnikami (światłem i temperaturą), więc nie wiadomo, który spowodował różnicę.', 'W poprawnym porównaniu różni się tylko jedna zmienna.'),
   T('podaj', 1, 'Sformułuj wniosek dotyczący wpływu wody na kiełkowanie nasion rzeżuchy.', 'Do kiełkowania nasion rzeżuchy niezbędna jest woda (bez wody nasiona nie kiełkują).', 'Wniosek z porównania A i C — dotyczy wody i nie wykracza poza rzeżuchę.'),
   T('wyjasnij', 1, 'Wyjaśnij, dlaczego do każdej szalki wysiano po 50 nasion, a nie po jednym.', 'Aby ograniczyć wpływ zmienności osobniczej i przypadku (np. martwego nasienia) — wynik jest bardziej wiarygodny.', 'Liczna próba = wiarygodność.')),
 B('Moczarka i światło',
   'Doświadczenie (autorskie). Gałązkę moczarki kanadyjskiej umieszczono w zlewce z wodą z dodatkiem NaHCO₃ w temperaturze 25°C. Lampę ustawiano w różnej odległości od zlewki i liczono pęcherzyki gazu wydzielane w ciągu minuty: 10 cm — 42; 20 cm — 24; 40 cm — 9; 80 cm — 3.',
   T('podaj', 1, 'Podaj, jaką funkcję pełni NaHCO₃ dodany do wody.', 'Jest źródłem CO₂ dla fotosyntezy — dzięki temu ilość CO₂ nie ogranicza procesu.', 'Warunek stały, który eliminuje CO₂ jako czynnik ograniczający.'),
   T('wyjasnij', 1, 'Wyjaśnij, dlaczego zmniejszanie odległości lampy zwiększa liczbę pęcherzyków.', 'Im bliżej lampa, tym większe natężenie światła, więc fotosystemy pochłaniają więcej energii, szybciej zachodzi faza zależna od światła (fotoliza wody) i wydziela się więcej tlenu.', 'Mechanizm: więcej światła → więcej wzbudzonego chlorofilu i fotolizy → więcej O₂.'),
   T('podaj', 1, 'Wskaż czynnik, który powinien być kontrolowany, a którego zmiana mogłaby zafałszować wynik przy zbliżaniu lampy, i zaproponuj sposób jego kontroli.', 'Temperatura wody (lampa grzeje) — można postawić między lampą a zlewką naczynie z wodą (filtr cieplny) lub użyć lampy LED i mierzyć temperaturę.', 'CKE pyta o funkcję elementów procedury — co kontroluje dany zabieg.'),
   T('rozstrzygnij', 1, 'Rozstrzygnij, czy liczba pęcherzyków jest dokładną miarą intensywności fotosyntezy. Uzasadnij.', 'Nie — pęcherzyki mogą mieć różną wielkość, część tlenu rozpuszcza się w wodzie lub jest zużywana w oddychaniu; to miara przybliżona.', 'Ocena ograniczeń metody to częsty typ polecenia.')),
 B('Lek i placebo',
   'Opis badania (autorski). 200 osób z nadciśnieniem losowo podzielono na dwie grupy. Grupa I przez 8 tygodni otrzymywała nowy lek, grupa II — identycznie wyglądające tabletki bez substancji czynnej. Ani pacjenci, ani lekarze mierzący ciśnienie nie wiedzieli, kto należy do której grupy. Średni spadek ciśnienia skurczowego: grupa I — 14 mm Hg, grupa II — 4 mm Hg (p < 0,01).',
   T('podaj', 1, 'Podaj nazwę takiego schematu badania.', 'Badanie z podwójnie ślepą próbą (z grupą kontrolną otrzymującą placebo, randomizowane).', 'Podwójnie ślepa — nie wiedzą ani badani, ani badacze.'),
   T('wyjasnij', 1, 'Wyjaśnij, dlaczego lekarze mierzący ciśnienie nie wiedzieli, kto otrzymuje lek.', 'Aby ich oczekiwania nie wpływały (nawet nieświadomie) na sposób pomiaru i interpretację wyników.', 'Eliminacja błędu obserwatora.'),
   T('wyjasnij', 1, 'Wyjaśnij, dlaczego w grupie II ciśnienie też nieco spadło.', 'Efekt placebo (oczekiwanie poprawy, mniejszy stres) lub naturalna zmienność ciśnienia; dlatego skuteczność leku ocenia się względem placebo, a nie względem zera.', 'Grupa kontrolna pokazuje, ile zmiany nie wynika z leku.'),
   T('podaj', 1, 'Na podstawie wyników sformułuj wniosek.', 'Nowy lek istotnie statystycznie obniża ciśnienie skurczowe u osób z nadciśnieniem (bardziej niż placebo).', 'p < 0,01 — różnica istotna; wniosek dotyczy badanej grupy (osoby z nadciśnieniem).')),
 B('Pleśń na chlebie',
   'Doświadczenie (autorskie). Sześć jednakowych kromek chleba bez konserwantów zwilżono taką samą ilością wody i zamknięto w woreczkach. Trzy woreczki trzymano w 25°C, trzy — w 4°C. Po 7 dniach mierzono powierzchnię pokrytą pleśnią: 25°C — 38%, 42%, 35%; 4°C — 3%, 0%, 2%.',
   T('podaj', 1, 'Oblicz średnią powierzchnię pokrytą pleśnią w każdej temperaturze.', '25°C — ok. 38,3%; 4°C — ok. 1,7%.', '(38+42+35)/3 = 38,3; (3+0+2)/3 = 1,7.'),
   T('podaj', 1, 'Podaj, w jakim celu każdą temperaturę badano na trzech kromkach.', 'Aby uwzględnić zmienność wyników (powtórzenia) i obliczyć średnią — wynik jest bardziej wiarygodny.', 'Powtórzenia.'),
   T('wyjasnij', 1, 'Wyjaśnij, dlaczego w lodówce pleśń rozwijała się wolniej.', 'Niska temperatura obniża aktywność enzymów grzyba, więc wolniej zachodzi metabolizm, wzrost strzępek i kiełkowanie zarodników.', 'Mechanizm: temperatura → aktywność enzymów → tempo wzrostu.'),
   T('rozstrzygnij', 1, 'Rozstrzygnij, czy na podstawie doświadczenia można stwierdzić, że chleb przechowywany w lodówce nigdy nie spleśnieje. Uzasadnij.', 'Nie — badanie trwało tylko 7 dni, a w 4°C pleśń też się pojawiła (wzrost spowolniony, nie zatrzymany).', 'Nie wolno ekstrapolować poza zakres danych.')),
 B('Korelacja a przyczyna',
   'Dane (przykładowe). W miastach, w których jest więcej bocianich gniazd, rodzi się więcej dzieci. Współczynnik korelacji między liczbą gniazd a liczbą urodzeń wynosi 0,8.',
   T('rozstrzygnij', 1, 'Rozstrzygnij, czy dane dowodzą, że bociany wpływają na liczbę urodzeń. Uzasadnij.', 'Nie — korelacja nie dowodzi związku przyczynowego; obie wielkości mogą zależeć od trzeciego czynnika (np. wielkości miasta lub liczby mieszkańców).', 'Klasyczny przykład pozornej zależności.'),
   T('podaj', 1, 'Zaproponuj, jak można by sprawdzić, czy zależność wynika z wielkości miast.', 'Porównać miasta o podobnej liczbie mieszkańców (lub przeliczyć dane na 1000 mieszkańców) i sprawdzić, czy korelacja nadal występuje.', 'Kontrola zmiennej zakłócającej.')),
 B('Wpływ pH na amylazę',
   'Doświadczenie (autorskie). Do pięciu probówek z 2 cm³ 1% roztworu skrobi i roztworami buforowymi o pH 3, 5, 7, 9 i 11 dodano po 1 cm³ rozcieńczonej śliny. Co 30 sekund pobierano kroplę mieszaniny na płytkę z płynem Lugola. Zanotowano czas, po którym kropla przestawała barwić się na granatowo: pH 3 — powyżej 10 min; pH 5 — 6 min; pH 7 — 2 min; pH 9 — 5 min; pH 11 — powyżej 10 min.',
   T('wyjasnij', 1, 'Wyjaśnij, dlaczego zanik granatowej barwy świadczy o działaniu amylazy.', 'Amylaza rozkłada skrobię do maltozy, a płyn Lugola barwi na granatowo tylko skrobię — gdy skrobia zostanie rozłożona, barwa zanika.', 'Wskaźnik reaguje na substrat, nie na produkt.'),
   T('podaj', 1, 'Podaj, przy którym pH amylaza ślinowa działała najszybciej, i określ, jaką zależność przedstawiają wyniki.', 'Przy pH 7; aktywność amylazy zależy od pH — jest największa przy pH obojętnym i maleje w środowisku kwaśnym i zasadowym.', 'Krótszy czas = wyższa aktywność.'),
   T('wyjasnij', 1, 'Wyjaśnij, dlaczego amylaza ślinowa przestaje działać w żołądku.', 'W żołądku jest kwaśne środowisko (pH ok. 2) — zmienia się jonizacja aminokwasów w centrum aktywnym, enzym zmienia kształt (denaturuje) i nie wiąże skrobi.', 'Zmiana pH → zmiana ładunków i struktury → utrata aktywności.'),
   T('podaj', 1, 'Zaproponuj próbę kontrolną do tego doświadczenia.', 'Probówka ze skrobią i buforem o pH 7, do której zamiast śliny dodano wodę destylowaną (lub zagotowaną ślinę) — skrobia nie powinna zniknąć.', 'Pokazuje, że rozkład skrobi zachodzi dzięki enzymowi ze śliny.')),
 B('Wykres w zadaniu',
   'Dane (autorskie). Zmierzono tempo pobierania tlenu przez myszy (cm³ O₂/g/h) w różnych temperaturach otoczenia: 5°C — 6,2; 10°C — 5,0; 20°C — 3,4; 30°C — 2,4; 35°C — 2,6.',
   T('podaj', 2, 'Narysuj wykres liniowy przedstawiający zależność tempa pobierania tlenu od temperatury otoczenia.', 'Oś X: temperatura otoczenia [°C] (5–35), oś Y: pobieranie tlenu [cm³ O₂ · g⁻¹ · h⁻¹]; równomierne skale, pięć poprawnie naniesionych punktów połączonych linią, tytuł lub opis.', '2 pkt — poprawnie opisane i wyskalowane osie oraz poprawnie naniesione punkty; 1 pkt — jeden z tych elementów.'),
   T('wyjasnij', 1, 'Wyjaśnij, dlaczego mysz zużywa więcej tlenu w niskiej temperaturze.', 'Mysz jest stałocieplna — w zimnie traci więcej ciepła, więc intensyfikuje oddychanie komórkowe (produkcję ciepła), na co zużywa więcej tlenu.', 'Termoregulacja wymaga energii z oddychania.')),
 B('Hipoteza czy wniosek?',
   'Zestaw zdań (autorski). 1. Czy stężenie soli wpływa na plazmolizę w komórkach skórki cebuli? 2. Im wyższe stężenie NaCl, tym większy odsetek komórek ulega plazmolizie. 3. W roztworze 10% NaCl plazmolizie uległo 95% komórek. 4. Stężenie soli w otoczeniu wpływa na plazmolizę komórek skórki cebuli.',
   T('przyporzadkuj', 1, 'Przyporządkuj zdaniom 1–4 nazwy: wynik, hipoteza, problem badawczy, wniosek.', '1 — problem badawczy; 2 — hipoteza; 3 — wynik; 4 — wniosek.', 'Problem = pytanie, hipoteza = przewidywanie przed badaniem, wynik = konkretna obserwacja, wniosek = uogólnienie po badaniu.')),
 B('Uzasadnienie w praktyce',
   'Polecenie (autorskie). „Rozstrzygnij, czy naczynie oznaczone X na schemacie serca ryby jest żyłą, czy tętnicą. Uzasadnij.” Na schemacie naczynie X wyprowadza krew z komory serca do skrzeli. Uczeń odpowiedział: „Tętnica, bo płynie w niej krew odtlenowana”.',
   T('rozstrzygnij', 1, 'Oceń, czy odpowiedź ucznia zasługuje na punkt. Uzasadnij swoją ocenę.', 'Nie — rozstrzygnięcie jest poprawne, ale uzasadnienie błędne: o tym, czy naczynie jest tętnicą, decyduje kierunek przepływu krwi (od serca), a nie stopień jej utlenowania.', 'Przykład z typowych błędów opisanych w sprawozdaniu CKE 2025.'),
   T('podaj', 1, 'Zapisz poprawne uzasadnienie.', 'Jest to tętnica, ponieważ odprowadza krew z serca (z komory) do skrzeli.', 'Uzasadnienie wskazuje cechę rozstrzygającą (kierunek przepływu).')),
 B('Wyjaśnij — przyczyna, mechanizm, skutek',
   'Odpowiedzi uczniów (autorskie) na polecenie „Wyjaśnij, dlaczego u osoby z niedoborem albumin pojawiają się obrzęki”: A — „Bo brakuje albumin.” B — „Albuminy zatrzymują wodę we krwi.” C — „Mało albumin obniża ciśnienie onkotyczne osocza, więc mniej wody wraca z płynu tkankowego do naczyń włosowatych i gromadzi się ona w tkankach.”',
   T('rozstrzygnij', 1, 'Wskaż odpowiedź, która jest pełnym wyjaśnieniem, i określ, czego brakuje w odpowiedzi B.', 'C; w odpowiedzi B brakuje powiązania z przyczyną (niedobór → spadek ciśnienia onkotycznego) i skutku (gromadzenie wody w tkankach — obrzęk).', 'Pełne wyjaśnienie zawiera przyczynę, mechanizm i skutek.')),
 B('Bioindykacja porostami',
   'Dane (autorskie). Na pniach drzew w pięciu punktach na linii od centrum miasta do lasu oznaczono liczbę gatunków porostów: centrum — 0; 2 km — 1; 5 km — 4; 10 km — 9; las 20 km — 15. Stężenie SO₂ w powietrzu malało w tym kierunku.',
   T('podaj', 1, 'Sformułuj wniosek na podstawie danych.', 'Liczba gatunków porostów rośnie wraz ze spadkiem zanieczyszczenia powietrza SO₂ (z odległością od centrum miasta).', 'Wniosek wiąże obie zmienne, ale nie twierdzi, że dowiedziono przyczyny.'),
   T('rozstrzygnij', 1, 'Rozstrzygnij, czy same dane dowodzą, że SO₂ jest przyczyną braku porostów w centrum. Uzasadnij.', 'Nie — to dane korelacyjne; na porosty mogą wpływać też inne czynniki zmieniające się wraz z odległością (pyły, wilgotność, gatunki drzew); potrzebne byłoby doświadczenie.', 'Odróżnianie korelacji od przyczyny.')),
 B('Średnia a mediana',
   'Dane (autorskie). Masa ciała (g) dziesięciu myszy z jednej populacji: 18, 19, 19, 20, 20, 21, 21, 22, 22, 48.',
   T('podaj', 1, 'Oblicz średnią i medianę masy ciała myszy.', 'Średnia = 23 g; mediana = 20,5 g.', 'Suma = 230 g, n = 10; mediana — średnia z 5. i 6. wartości (20 i 21).'),
   T('wyjasnij', 1, 'Wyjaśnij, dlaczego w tym przypadku mediana lepiej opisuje typową masę myszy niż średnia.', 'Bo jedna mysz o masie 48 g (wartość odstająca) zawyża średnią, a mediana jest na wartości skrajne mało wrażliwa.', 'Wybór miary tendencji centralnej.')),
 B('Słupki błędu',
   'Wykres (opis, autorski). Średnia wysokość siewek fasoli po 14 dniach: nawożone — 18 cm (odchylenie standardowe ±6 cm), nienawożone — 16 cm (±5 cm). W każdej grupie było 5 roślin.',
   T('rozstrzygnij', 1, 'Rozstrzygnij, czy na podstawie tych wyników można uznać, że nawóz zwiększa wysokość siewek fasoli. Uzasadnij.', 'Nie można tego pewnie stwierdzić — różnica średnich (2 cm) jest mała w porównaniu z rozrzutem wyników (±5–6 cm), a grupy są małe; różnica może być przypadkowa.', 'Nakładające się słupki błędu i mała liczebność.'),
   T('podaj', 1, 'Zaproponuj zmianę w doświadczeniu, która zwiększy jego wiarygodność.', 'Zwiększenie liczby roślin w grupach (np. do 30) i/lub powtórzenie doświadczenia, a następnie test statystyczny.', 'Większa próba zmniejsza wpływ przypadku.')),
 B('Wniosek poza danymi',
   'Badanie (autorskie). Szczurom podawano przez 4 tygodnie dietę z dodatkiem związku X. W porównaniu z grupą kontrolną zmniejszyło się u nich stężenie cholesterolu LDL we krwi o 20%. Uczeń sformułował wniosek: „Związek X chroni ludzi przed zawałem serca”.',
   T('wyjasnij', 2, 'Podaj dwa powody, dla których wniosek ucznia wykracza poza dane z badania.', 'Np. 1) badanie przeprowadzono na szczurach, a nie na ludziach; 2) mierzono stężenie LDL, a nie częstość zawałów (nie badano skutków klinicznych); 3) badanie trwało tylko 4 tygodnie.', 'Każdy trafny powód — 1 pkt. Rekomendacja CKE: kontroluj zakres wnioskowania.')),
]}
